#include "mops/decode.hpp"
#include "support/printers.hpp"
#include <cstdint>
#include <fstream>
#include <gtest/gtest.h>
#include <sstream>
#include <stdexcept>
#include <string>

// compares mops::decode against tests/data/decode_golden.txt
// decode_golden.txt generated by tools/gen_decode_golden.py

namespace {

struct GoldenEntry {
  std::uint32_t word;
  mops::DecodeResult golden;
};

// parse as int and cast to std::uint8_t to avoid char behaviour
std::uint8_t parse_uint8(std::istringstream& in) {
  int value{};
  in >> value;
  return static_cast<std::uint8_t>(value);
}

bool parse_bool(std::istringstream& in) {
  bool value{};
  in >> value;
  return value;
}

mops::Stage parse_stage(const std::string& stage) {
  if (stage == "p") {
    return mops::Stage::Prologue;
  }
  if (stage == "m") {
    return mops::Stage::Main;
  }
  if (stage == "e") {
    return mops::Stage::Epilogue;
  }
  throw std::runtime_error("Unknown stage: " + stage);
}

GoldenEntry parse_line(const std::string& line) {
  std::istringstream in{line};

  std::string word_text;
  std::string result_text;
  in >> word_text >> result_text;

  const std::uint32_t word{static_cast<std::uint32_t>(std::stoul(word_text, nullptr, 16))};

  if (result_text == "undefined") {
    return GoldenEntry{.word = word, .golden = mops::Undefined{}};
  }
  if (result_text != "ok") {
    throw std::runtime_error("Unknown result in: " + line);
  }

  std::string family_text;
  std::string stage_text;
  in >> family_text >> stage_text;

  const mops::Stage stage{parse_stage(stage_text)};

  const std::uint8_t rd{parse_uint8(in)};
  const std::uint8_t rs{parse_uint8(in)};
  const std::uint8_t rn{parse_uint8(in)};

  const bool r_unpriv{parse_bool(in)};
  const bool r_nt{parse_bool(in)};
  const bool w_unpriv{parse_bool(in)};
  const bool w_nt{parse_bool(in)};

  // any parse failed
  if (!in) {
    throw std::runtime_error("Malformed line: " + line);
  }

  const mops::AccessAttributes read{.unprivileged = r_unpriv, .non_temporal = r_nt};
  const mops::AccessAttributes write{.unprivileged = w_unpriv, .non_temporal = w_nt};

  if (family_text == "set") {
    return GoldenEntry{.word = word,
                       .golden = mops::SetInstruction{.stage = stage, .rd = rd, .rs = rs, .rn = rn, .write = write}};
  }
  if (family_text == "cpy" || family_text == "cpyf") {
    const mops::CpyFamily cpy_family{(family_text == "cpyf") ? mops::CpyFamily::CpyF : mops::CpyFamily::Cpy};
    return GoldenEntry{
        .word = word,
        .golden = mops::CpyInstruction{
            .family = cpy_family, .stage = stage, .rd = rd, .rs = rs, .rn = rn, .read = read, .write = write}};
  }
  throw std::runtime_error("Unknown family: " + line);
}

} // namespace

TEST(DecodeGolden, MatchesGoldenFile) {
  std::ifstream in{MOPS_GOLDEN_FILE};
  ASSERT_TRUE(in.is_open()) << "Cannot open " << MOPS_GOLDEN_FILE;

  int checked{0};
  int failed{0};

  std::string line;
  while (std::getline(in, line)) {
    if (line.empty()) {
      continue;
    }

    const GoldenEntry entry{parse_line(line)};
    const mops::DecodeResult actual{mops::decode(entry.word)};
    checked++;

    if (actual != entry.golden) {
      failed++;
      ADD_FAILURE() << "Golden line: " << line << "\nExpected: " << testing::PrintToString(entry.golden)
                    << "\nActual: " << testing::PrintToString(actual);
    }
  }

  EXPECT_GT(checked, 0) << "Golden file is empty";
  EXPECT_EQ(failed, 0) << failed << " of " << checked << " results differ";
}